const html="<!doctype html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; script-src 'sha256-7nSckWjdSZC9vEqy/Wgd2R7hu0P3Gk22B4FN1Noj3/o='; connect-src 'none'; base-uri 'none'; form-action 'none'; object-src 'none'\"><meta name=\"referrer\" content=\"no-referrer\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Agriya Agro Tech \u2014 Rooted in agriculture</title><meta name=\"description\" content=\"Explore Agriya Agro Tech, agricultural product categories, crop nutrition and dealer enquiries.\"><style>\n:root{--green:#163d2b;--lime:#d7e5a0;--cream:#f7f6ee;--muted:#687266}*{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth;scroll-padding-top:100px}body{margin:0;background:var(--cream);font-family:Arial,sans-serif;color:var(--green)}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button,a,input,select,textarea{outline-offset:5px}header{height:94px;padding:0 5%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ddd;background:var(--cream);position:sticky;top:0;z-index:5}.brand{display:flex;gap:12px;align-items:center;font-size:27px;font-weight:800;letter-spacing:-1px}.brand small{display:block;font-size:10px;letter-spacing:3px;margin-top:4px}.mark{font-size:33px;background:var(--green);color:var(--lime);border-radius:50%;width:49px;height:49px;display:grid;place-items:center}nav{display:flex;gap:30px;font-size:13px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:24px;background:var(--green);color:white;padding:16px 24px;border:0;border-radius:5px;cursor:pointer;font-size:13px}.btn.light{background:var(--lime);color:var(--green)}.outline{background:transparent;border:1px solid #b6bfb5;color:var(--green)}.menu{display:none}.hero{padding:58px 5% 28px;display:grid;grid-template-columns:1fr 1.04fr;gap:5%;align-items:center}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:bold;text-transform:uppercase;display:flex;align-items:center;gap:10px}.eyebrow:before{content:'';height:7px;width:7px;background:#8fa84c;border-radius:50%}h1{font-family:Georgia,serif;font-weight:400;font-size:clamp(48px,5.4vw,82px);letter-spacing:-3px;line-height:1.06;margin:25px 0}h1 em{color:#708a3c;font-weight:400}p{line-height:1.75;color:var(--muted);font-size:15px}.hero p{max-width:430px}.actions{display:flex;gap:12px;margin-top:30px}.hero-photo{position:relative;height:570px;border-radius:150px 10px 10px 10px;overflow:hidden;background:#49643d}.hero-photo img{width:100%;height:100%;object-fit:cover}.photo-label{position:absolute;bottom:24px;left:24px;right:24px;padding:20px;background:#f7f6eeed;border-radius:5px;display:flex;justify-content:space-between;align-items:center;font-size:13px}.photo-label strong{font-family:Georgia,serif;font-size:21px;display:block;margin-bottom:6px}.hero-note{font-size:11px;border-top:1px solid #d9ddd0;padding-top:20px;margin-top:36px;display:flex;gap:18px}.strip{margin:30px 5% 0;padding:27px 0;border-top:1px solid #d5dacd;border-bottom:1px solid #d5dacd;display:flex;justify-content:space-between;font-size:12px;letter-spacing:1px}.strip span:before{content:'\u2733';color:#829744;margin-right:12px}section{padding:90px 5%}.section-head{display:flex;justify-content:space-between;align-items:end;gap:40px;margin-bottom:35px}h2{font-family:Georgia,serif;font-size:clamp(34px,3.5vw,52px);font-weight:400;letter-spacing:-1.5px;margin:15px 0}.section-head p{max-width:350px}.filters{display:flex;gap:10px;flex-wrap:wrap;margin:25px 0}.filter{border:1px solid #ced3c5;background:transparent;color:var(--green);border-radius:30px;padding:10px 18px;cursor:pointer;font-size:12px}.filter.active{background:var(--green);color:white}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.product{border:1px solid #d7ddce;border-radius:8px;overflow:hidden;background:#fff}.product-art{height:230px;background:#e8eddf;display:grid;place-items:center;position:relative}.product:nth-child(2) .product-art{background:#eee8d6}.product:nth-child(3) .product-art{background:#e3e9e4}.bottle{width:84px;height:134px;background:#fafbf5;border:1px solid #d0d9c7;border-radius:13px 13px 17px 17px;box-shadow:15px 16px 20px #163d2b17;position:relative;display:grid;place-items:center;text-align:center;font-weight:800;font-size:12px}.bottle:before{content:'';position:absolute;top:-22px;background:#28543a;width:48px;height:24px;border-radius:5px 5px 0 0}.bottle span{background:#28543a;color:#e5eecc;width:100%;padding:17px 5px}.bottle small{display:block;font-size:8px;font-weight:normal;margin-top:8px}.demo{position:absolute;top:15px;left:15px;font-size:9px;text-transform:uppercase;letter-spacing:1px;color:#6c7761}.product-body{padding:25px}.product h3{font-family:Georgia,serif;font-size:25px;font-weight:400;margin:0}.product p{font-size:13px;min-height:65px}.text-button{border:0;background:transparent;padding:0;color:var(--green);font-size:12px;font-weight:bold;cursor:pointer}.catalogue-note{font-size:12px}.crops{background:var(--green);color:var(--cream)}.crops p{color:#b9c9bb}.crop-tabs{display:flex;gap:12px;flex-wrap:wrap;margin:25px 0}.crop-tabs button{border:1px solid #547160;color:#eee;background:transparent;padding:13px 24px;border-radius:5px;cursor:pointer}.crop-tabs button.active{background:var(--lime);color:var(--green)}.crop-detail{display:grid;grid-template-columns:1fr 1fr;gap:70px;padding-top:20px;border-top:1px solid #496451}.crop-detail h3{font-family:Georgia,serif;font-size:35px;font-weight:400}.crop-detail ul{padding:0;list-style:none}.crop-detail li{padding:17px 0;border-bottom:1px solid #46614e;font-size:14px}.crop-detail li:before{content:'\u2197';color:var(--lime);margin-right:16px}.about{display:grid;grid-template-columns:1fr 1fr;gap:8%;align-items:center}.about-img{height:400px;border-radius:8px;object-fit:cover;width:100%}.about .eyebrow{margin-top:15px}.values{display:flex;gap:35px;border-top:1px solid #d0d7c6;padding-top:25px;margin-top:30px;font-size:12px}.contact{background:#e9eddf;display:grid;grid-template-columns:1fr 1fr;gap:8%}form{display:grid;grid-template-columns:1fr 1fr;gap:17px}label{font-size:12px;display:grid;gap:9px}input,select,textarea{width:100%;border:1px solid #c5cfbc;background:#f8faf4;padding:13px;border-radius:4px;color:var(--green)}.full{grid-column:1/-1}textarea{resize:vertical;min-height:95px}.notice{font-size:12px;margin:12px 0}.contact h2{max-width:420px}.form-status{white-space:pre-wrap;line-height:1.7;font-size:13px;margin:0}footer{padding:35px 5%;display:flex;justify-content:space-between;gap:20px;align-items:center;font-size:11px}footer .brand{font-size:21px}dialog{border:0;border-radius:12px;padding:34px;max-width:520px;width:90%;color:var(--green);background:var(--cream)}dialog::backdrop{background:#092317aa}dialog h2{font-size:32px}.close{float:right;border:0;background:transparent;font-size:25px;cursor:pointer;color:var(--green)}@media(max-width:900px){nav{gap:15px}header>.btn{display:none}.hero{gap:25px}.hero-photo{height:480px}.grid{gap:12px}.product-body{padding:18px}.strip{gap:15px;flex-wrap:wrap}}@media(max-width:650px){header{height:78px}.brand{font-size:23px}.menu{display:block;border:0;background:none;color:var(--green);font-size:23px}nav{display:none;position:absolute;top:78px;left:0;right:0;background:var(--cream);padding:25px;flex-direction:column;border-bottom:1px solid #ccc}nav.open{display:flex}.hero{grid-template-columns:1fr;padding-top:40px}h1{font-size:57px}.hero-photo{height:390px;border-radius:90px 8px 8px 8px}.hero-note{margin-top:25px}.strip{font-size:10px}.section-head{display:block}section{padding:60px 5%}.grid,.about,.contact,.crop-detail{grid-template-columns:1fr}.grid{gap:24px}.product p{min-height:0}.product-art{height:210px}.about,.contact{gap:30px}.about-img{height:280px}.crop-detail{gap:10px}footer{flex-wrap:wrap}.actions{flex-wrap:wrap}}\n</style></head><body><header><a class=\"brand\" href=\"#home\" aria-label=\"Agriya Agro Tech home\"><span class=\"mark\">\u2767</span><span>AGRIYA<small>AGRO TECH</small></span></a><nav id=\"nav\"><a href=\"#home\">Home</a><a href=\"#products\">Products</a><a href=\"#crops\">Crop solutions</a><a href=\"#about\">About us</a></nav><a class=\"btn\" href=\"#contact\">Let\u2019s grow together <span>\u2197</span></a><button class=\"menu\" aria-label=\"Toggle navigation\" aria-expanded=\"false\">\u2630</button></header>\n<main><div class=\"hero\" id=\"home\"><div><div class=\"eyebrow\">Agriya Agro Tech</div><h1>Rooted in care.<br>Growing a<br><em>better tomorrow.</em></h1><p>Agriculture begins with understanding the field. Explore crop nutrition, soil care and possibilities for your next growing season.</p><div class=\"actions\"><a class=\"btn\" href=\"#products\">Explore our products <span>\u2197</span></a><a class=\"btn outline\" href=\"#contact\">Make an enquiry</a></div><div class=\"hero-note\"><span>SOIL FIRST</span><span>\u2022</span><span>CROP FOCUSED</span><span>\u2022</span><span>GROW TOGETHER</span></div></div><div class=\"hero-photo\"><img src=\"field.jpg\" alt=\"Green agricultural fields in warm evening sunlight\"><div class=\"photo-label\"><div><strong>Every field holds a possibility.</strong>Let\u2019s start with yours.</div><span>\u2197</span></div></div></div><div class=\"strip\"><span>Crop nutrition</span><span>Soil care</span><span>Plant health</span><span>Dealer partnerships</span></div>\n<section id=\"products\"><div class=\"section-head\"><div><div class=\"eyebrow\">Explore the range</div><h2>Care for every stage<br>of growth.</h2></div><p>Discover the areas of agricultural care. Ask us about product availability and the right information for your crop.</p></div><div class=\"filters\" aria-label=\"Filter product categories\"><button class=\"filter active\" data-filter=\"all\">All categories</button><button class=\"filter\" data-filter=\"nutrition\">Crop nutrition</button><button class=\"filter\" data-filter=\"soil\">Soil care</button><button class=\"filter\" data-filter=\"plant\">Plant health</button></div><div class=\"grid\"><article class=\"product\" data-category=\"nutrition\"><div class=\"product-art\"><span class=\"demo\">Illustrative packaging</span><div class=\"bottle\"><span>AGRIYA<small>CROP NUTRITION</small></span></div></div><div class=\"product-body\"><h3>Crop nutrition</h3><p>Explore plant nutrition and discuss crop stage, visible symptoms and nutrient requirements.</p><button class=\"text-button\" data-detail=\"nutrition\">Explore category \u2197</button></div></article><article class=\"product\" data-category=\"soil\"><div class=\"product-art\"><span class=\"demo\">Illustrative packaging</span><div class=\"bottle\"><span>AGRIYA<small>SOIL CARE</small></span></div></div><div class=\"product-body\"><h3>Soil care</h3><p>Start below the surface with a conversation about soil conditions, testing and field preparation.</p><button class=\"text-button\" data-detail=\"soil\">Explore category \u2197</button></div></article><article class=\"product\" data-category=\"plant\"><div class=\"product-art\"><span class=\"demo\">Illustrative packaging</span><div class=\"bottle\"><span>AGRIYA<small>PLANT HEALTH</small></span></div></div><div class=\"product-body\"><h3>Plant health</h3><p>Understand crop observations and share your field concerns before choosing a product.</p><button class=\"text-button\" data-detail=\"plant\">Explore category \u2197</button></div></article></div><p class=\"catalogue-note\">Catalogue preview: category names and packaging are illustrative. Confirmed products and labels will be added to the range.</p></section>\n<section class=\"crops\" id=\"crops\"><div class=\"section-head\"><div><div class=\"eyebrow\">Begin with your crop</div><h2>Different crops.<br>A thoughtful approach.</h2></div><p>A useful enquiry starts with the crop, its growing stage and what you observe in the field.</p></div><div class=\"crop-tabs\" role=\"group\" aria-label=\"Select a crop\"><button class=\"active\" data-crop=\"Paddy\">Paddy</button><button data-crop=\"Coconut\">Coconut</button><button data-crop=\"Banana\">Banana</button><button data-crop=\"Vegetables\">Vegetables</button></div><div class=\"crop-detail\" aria-live=\"polite\"><div><h3 id=\"crop-title\">Let\u2019s talk about your paddy.</h3><p id=\"crop-copy\">Share the crop age, leaf colour and tillering observations to give your enquiry a clear starting point.</p><a class=\"btn light\" id=\"crop-enquiry\" href=\"#contact\">Enquire about paddy \u2197</a></div><ul id=\"crop-list\"><li>Crop age and current growing stage</li><li>Leaf colour and tillering observations</li><li>Soil and irrigation conditions</li></ul></div></section>\n<section class=\"about\" id=\"about\"><img class=\"about-img\" src=\"field.jpg\" alt=\"Open farmland with cultivated fields\" loading=\"lazy\"><div><div class=\"eyebrow\">About Agriya</div><h2>Closer to the soil.<br>Closer to the grower.</h2><p>Welcome to Agriya Agro Tech. This is a space to explore agricultural care, ask product questions and begin a conversation about your field.</p><p>Whether you are a farmer exploring crop needs or a dealer interested in connecting, your enquiry is the starting point.</p><div class=\"values\"><span>Understand the field</span><span>Ask better questions</span><span>Grow connections</span></div></div></section>\n<section class=\"contact\" id=\"contact\"><div><div class=\"eyebrow\">Let\u2019s connect</div><h2>A new season.<br>A new conversation.</h2><p>Preparing for your crop or exploring a dealer partnership? Create an enquiry with the details that matter.</p><p class=\"notice\">Enquiry preview: this form prepares a message for you to copy. Delivery will be enabled when the company\u2019s contact details are added.</p></div><form id=\"enquiry\"><label>Your name<input name=\"name\" maxlength=\"100\" autocomplete=\"name\" required placeholder=\"Enter your name\"></label><label>Phone number<input name=\"phone\" maxlength=\"30\" type=\"tel\" autocomplete=\"tel\" required placeholder=\"Your contact number\"></label><label>I am a<select name=\"role\"><option>Farmer</option><option>Dealer / Distributor</option><option>Other</option></select></label><label>Crop / interest<select name=\"crop\" id=\"enquiry-crop\"><option>General enquiry</option><option>Paddy</option><option>Coconut</option><option>Banana</option><option>Vegetables</option><option>Dealer partnership</option></select></label><label class=\"full\">Your location<input name=\"location\" maxlength=\"150\" placeholder=\"Town / district\"></label><label class=\"full\">Tell us more<textarea name=\"message\" maxlength=\"2000\" placeholder=\"Crop stage, product question or partnership enquiry\" required></textarea></label><button class=\"btn full\" type=\"submit\">Prepare my enquiry \u2197</button><p class=\"form-status full\" id=\"form-status\" aria-live=\"polite\"></p><button class=\"btn outline full\" type=\"button\" id=\"copy\" hidden>Copy enquiry</button></form></section></main><footer><a class=\"brand\" href=\"#home\">AGRIYA <small>AGRO TECH</small></a><span>Rooted in agriculture. Growing connections.</span><span>\u00a9 <span id=\"year\"></span> Agriya Agro Tech</span></footer><dialog id=\"detail\"><button class=\"close\" aria-label=\"Close category details\">\u00d7</button><div class=\"eyebrow\">Product category</div><h2 id=\"detail-title\"></h2><p id=\"detail-copy\"></p><p class=\"notice\">Product specifications, packaging and availability are awaiting company confirmation.</p><a class=\"btn\" href=\"#contact\" id=\"detail-enquiry\">Enquire about this category \u2197</a></dialog><script>\nconst q=s=>document.querySelector(s);q('#year').textContent=new Date().getFullYear();q('.menu').onclick=()=>{const open=q('#nav').classList.toggle('open');q('.menu').setAttribute('aria-expanded',open)};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{q('#nav').classList.remove('open');q('.menu').setAttribute('aria-expanded','false')});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.product').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter)});const details={nutrition:['Crop nutrition','Tell us about your crop, its current stage and any visible symptoms. Confirmed product names and nutrient specifications will be listed here.'],soil:['Soil care','Share soil test information, field conditions and your preparation plans. Confirmed soil-care product details will be listed here.'],plant:['Plant health','Describe what you see in the field, when it began and which part of the crop is affected. Confirmed plant-health product details will be listed here.']};document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const d=details[b.dataset.detail];q('#detail-title').textContent=d[0];q('#detail-copy').textContent=d[1];q('#detail').showModal()});q('.close').onclick=()=>q('#detail').close();q('#detail-enquiry').onclick=()=>q('#detail').close();const cropNotes={Paddy:['crop age, leaf colour and tillering observations','Leaf colour and tillering observations'],Coconut:['palm age, leaf appearance and fruit-set observations','Leaf appearance and fruit-set observations'],Banana:['plant age, leaf appearance and bunch development','Leaf appearance and bunch development'],Vegetables:['crop variety, plant age and flowering observations','Crop variety and flowering observations']};document.querySelectorAll('[data-crop]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-crop]').forEach(x=>x.classList.toggle('active',x===b));const c=b.dataset.crop;q('#crop-title').textContent='Let\u2019s talk about your '+c.toLowerCase()+'.';q('#crop-copy').textContent='Share the '+cropNotes[c][0]+' to give your enquiry a clear starting point.';q('#crop-list').children[1].textContent=cropNotes[c][1];q('#crop-enquiry').textContent='Enquire about '+c.toLowerCase()+' \u2197';q('#enquiry-crop').value=c});let message='';q('#enquiry').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));message='Agriya Agro Tech enquiry\\nName: '+d.name+'\\nPhone: '+d.phone+'\\nRole: '+d.role+'\\nInterest: '+d.crop+'\\nLocation: '+d.location+'\\nMessage: '+d.message;q('#form-status').textContent='Your enquiry is ready. It has not been sent.\\n\\n'+message;q('#copy').hidden=false};q('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(message);q('#copy').textContent='Enquiry copied \u2713'}catch{q('#copy').textContent='Select and copy the enquiry text above'}};\n</script></body></html>\n";
