const csp="default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; script-src 'sha256-7nSckWjdSZC9vEqy/Wgd2R7hu0P3Gk22B4FN1Noj3/o='; connect-src 'none'; base-uri 'none'; form-action 'none'; object-src 'none'; frame-ancestors 'none'";
export default {async fetch(request){const url=new URL(request.url);const headers={"X-Content-Type-Options":"nosniff","Referrer-Policy":"no-referrer","Permissions-Policy":"camera=(), microphone=(), geolocation=()","X-Frame-Options":"DENY","Strict-Transport-Security":"max-age=31536000","Content-Security-Policy":csp};if(!["GET","HEAD"].includes(request.method))return new Response("Method not allowed",{status:405,headers:{...headers,Allow:"GET, HEAD"}});if(url.pathname==="/field.jpg"){headers["Content-Type"]="image/jpeg";headers["Cache-Control"]="public, max-age=86400";return new Response(request.method==="HEAD"?null:Uint8Array.from(atob(image),c=>c.charCodeAt(0)),{headers});}if(!["/","/index.html"].includes(url.pathname))return new Response("Page not found",{status:404,headers});headers["Content-Type"]="text/html; charset=utf-8";return new Response(request.method==="HEAD"?null:html,{headers});}};